draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure representing the controlled people
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw a hypodermic needle representing the pleasure control
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 50, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 30, 10, 0, 2*Math.PI);
  ctx.stroke();

  // animate the needle to simulate the control
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 50 + Math.sin(t)*20, H/2 + 30);
  ctx.stroke();

  ctx.restore();
}
